INSERT INTO `autoexec_customtemplate` VALUES (827472484507648,'k8s发布面板',1,'<div id=\"app\">\n  <Divider orientation=\"start\">Deployment</Divider>\n  <Row v-if=\"k8s_data && k8s_data.deployment\" class=\"pb-nm\">\n    <Col span=\"4\">\n    <div class=\"text-title\">名称</div>\n    <div>{{ k8s_data.deployment.name }}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">命名空间</div>\n    <div>{{ k8s_data.deployment.namespace }}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">创建时间</div>\n    <div>{{ k8s_data.deployment.creationTimestamp | formatDate }}</div>\n    </Col>\n	</Row>\n	\n	<div class=\"pb-nm\" v-if=\"k8s_data && k8s_data.deployment\">\n     <div class=\"pb-sm\">标签</div>\n     <Tag v-for=\"(value, key, index) in k8s_data.deployment.labels\" :key=\"index\">{{ key }}:{{ value }}</Tag>\n	</div>\n	\n	<Divider orientation=\"start\">New ReplicaSet</Divider>\n	<Row v-if=\"k8s_data.newreplicaset\" class=\"pb-nm\">\n    <Col span=\"8\">\n    <div class=\"text-title\">名称</div>\n    <div>{{ k8s_data.newreplicaset.name }}</div>\n    </Col>\n    <Col span=\"4\">\n      <div class=\"text-title\">就绪Pods</div>\n      <div :class=\"k8s_data.newreplicaset.readyReplicas==k8s_data.newreplicaset.replicas?\'text-success\':\'text-danger\'\">{{k8s_data.newreplicaset.readyReplicas}}/{{k8s_data.newreplicaset.replicas}}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">命名空间</div>\n    <div>{{ k8s_data.newreplicaset.namespace }}</div>\n    </Col>\n    <Col span=\"4\">\n    <div class=\"text-title\">创建时间</div>\n    <div>{{ k8s_data.newreplicaset.creationTimestamp | formatDate }}</div>\n    </Col>\n	</Row>\n	\n	<div class=\"pb-nm\" v-if=\"k8s_data.newreplicaset\">\n     <div class=\"pb-sm\">标签</div>\n     <Tag v-for=\"(value, key, index) in k8s_data.newreplicaset.labels\" :key=\"index\">{{ key }}:{{ value }}</Tag>\n	</div>\n	\n	<Divider orientation=\"start\">Pods</Divider>\n	<TsTable\n    v-if=\"k8s_data.newreplicaset && k8s_data.newreplicaset.pods\"\n    :theadList=\"theadList\"\n    :tbodyList=\"k8s_data.newreplicaset.pods\"\n    :fixedHeader=\"false\"\n     >\n      <template v-slot:name=\"{row}\">\n        <div :class=\"row.ready==1?\'text-success\':\'text-danger\'\">{{row.name}}</div>\n      </template>\n      <template v-slot:podIP=\"{row}\">\n      <div>{{row.podIP}}</div>\n      </template>\n      <template v-slot:nodeName=\"{row}\">\n        <div>{{row.nodeName}}</div>\n        </template>\n      <template v-slot:containerCount=\"{row}\">\n        <div :class=\"row.readyContainerCount==row.containerCount?\'text-success\':\'text-danger\'\">{{row.readyContainerCount}}/{{row.containerCount}}</div>\n      </template>\n      <template v-slot:startTime=\"{row}\">\n        <div>{{row.startTime | formatDate}}</div>\n      </template>\n      <template v-slot:containers=\"{row}\">\n        <div v-for=\"(item,index) in row.containers\" :key=\"index\">\n            <div :class=\"item.ready==1?\'text-success\':\'text-danger\'\">{{ item.image}}</div>\n        </div> \n      </template>\n       <template v-slot:labels=\"{row}\">\n        <Tag v-for=\"(value, key, index) in row.labels\" :key=\"index\">{{ key }}:{{ value }}</Tag> \n      </template>\n    </TsTable>\n</div>','{\n	data(){\n      return{\n      	k8s_data:{}\n      }	\n	},\n   computed:{\n 		theadList(){\n          return [\n            { key: \'name\', title: \'名称\' },\n            { key: \'podIP\', title: \'IP\' },\n            { key: \'nodeName\', title: \'节点\' },\n            { key: \'readyContainerCount\', title: \'就绪数量\' },\n            { key: \'startTime\', title: \'启动时间\' },	\n            { key: \'containers\', title: \'容器\' },\n            { key: \'labels\', title: \'标签\' }\n          ];\n        }\n   }\n}','2023-02-15 08:40:07.733','c8dea216f5bd49349db05cbc87db2f9a','2024-06-08 03:07:26.957','c8dea216f5bd49349db05cbc87db2f9a');
/*!40000 ALTER TABLE `autoexec_customtemplate` ENABLE KEYS */;

