INSERT INTO `datawarehouse_datasource` VALUES (653539042926592,'CiEntityCount','配置项分类统计',NULL,'<datasource name=\"CiEntityCount\" label=\"配置项分类统计\">\n  <fields>\n    <id column=\"ciEntityCount\" label=\"数量\" type=\"number\"/>\n    <field column=\"ciName\" label=\"类型\" type=\"text\"/>\n  </fields>\n  <select>\nSELECT\n	count( a.id ) as ciEntityCount,\n	b.label as ciName\nFROM\n	cmdb_cientity a\n	JOIN cmdb_ci b ON a.ci_id = b.id \nGROUP BY\n	b.label  </select>\n</datasource>',1,'0 0 3 * * ? *','replace',1,NULL,'done',6,'day','mysql',NULL,'2025-09-27 19:00:00.002','2025-09-27 19:00:00.359','2025-09-28 19:00:00.000'),(653541576286208,'CiCount','模型分类统计',NULL,'<datasource name=\"CiCount\" label=\"配置模型分类统计\">\n  <fields>\n    <id column=\"ciCount\" label=\"数量\" type=\"number\"/>\n    <field column=\"typeName\" label=\"类型\" type=\"text\"/>\n  </fields>\n  <select>\nSELECT\n	count( a.id ) as ciCount,\n	b.name as typeName \nFROM\n	cmdb_ci a\n	JOIN cmdb_citype b ON a.type_id = b.id \nGROUP BY\n	b.`name`  \n  </select>\n</datasource>',1,'0 0 3 ? * SUN *','replace',NULL,NULL,'done',13,NULL,'mysql',NULL,'2025-09-27 19:00:00.008','2025-09-27 19:00:00.356','2025-10-04 19:00:00.000'),(653561968992257,'CiEntityTypeCount','配置项数量',NULL,'<datasource name=\"OSCount\" label=\"操作系统数量\">\n  <fields>\n    <field column=\"ciEntityCount\" label=\"数量\" type=\"number\"/>\n  <id column=\"name\" label=\"名称\" type=\"text\"/>\n  </fields>\n  <select>\nSELECT\n	count( 1 ) as ciEntityCount,\n	\'数据库\' AS NAME \nFROM\n	cmdb_cientity \nWHERE\n	ci_id IN (\n	SELECT\n		id \n	FROM\n		cmdb_ci \n	WHERE\n		lft &gt;= ( SELECT lft FROM cmdb_ci WHERE id = 573130988855296 ) \n	AND rht &lt;= ( SELECT rht FROM cmdb_ci WHERE id = 573130988855296 )) UNION\nSELECT\n	count( 1 ) AS ciEntityCount,\n	\'操作系统\' AS NAME \nFROM\n	cmdb_cientity \nWHERE\n	ci_id IN (\n	SELECT\n		id \n	FROM\n		cmdb_ci \n	WHERE\n		lft &gt;= ( SELECT lft FROM cmdb_ci WHERE id = 479593471418368 ) \n	AND rht &lt;= ( SELECT rht FROM cmdb_ci WHERE id = 479593471418368 )) UNION\nSELECT\n	count( 1 ) AS ciEntityCount,\n	\'网络设备\' AS NAME \nFROM\n	cmdb_cientity \nWHERE\n	ci_id IN (\n	SELECT\n		id \n	FROM\n		cmdb_ci \n	WHERE\n		lft &gt;= ( SELECT lft FROM cmdb_ci WHERE id = 441115220123648 ) \n	AND rht &lt;= ( SELECT rht FROM cmdb_ci WHERE id = 441115220123648 )) UNION\nSELECT\n	count( 1 ) AS ciEntityCount,\n	\'服务器\' AS NAME \nFROM\n	cmdb_cientity \nWHERE\n	ci_id IN (\n	SELECT\n		id \n	FROM\n		cmdb_ci \n	WHERE\n	lft &gt;= ( SELECT lft FROM cmdb_ci WHERE id = 480157781467136 ) \n	AND rht &lt;= ( SELECT rht FROM cmdb_ci WHERE id = 480157781467136 ))\n  </select>\n</datasource>',1,NULL,'replace',NULL,NULL,'done',4,NULL,'mysql',NULL,NULL,NULL,NULL),(785413245509632,'cmdbAutoCollectionChange','cmdb大屏-自动采集数据变更情况',NULL,'<datasource name=\"cmdbAutoCollectionChange\" label=\"自动采集数据变更情况\">\n  <fields>\n    <field column=\"count\" label=\"数量\" type=\"number\"/>\n    <field column=\"name\" label=\"名称\" type=\"text\"/>\n    <field column=\"type\" label=\"类型\" type=\"text\"/>\n  </fields>\n  <select>\nselect count(1) as count, \'IP软硬件\' as `name`, \'新增\' as type from cmdb_cientity_transaction where action = \'insert\' and transaction_id in\n(\nSELECT\n	id\nFROM\n	cmdb_transaction \nWHERE\n  input_from = \'autoexec\'\n	and\n	ci_id IN (\n	SELECT\n		id \n	FROM\n		cmdb_ci \n	WHERE\n		lft &gt;= ( SELECT lft FROM cmdb_ci WHERE `name` = \'IPObject\' ) \n	AND rht &lt;= ( SELECT rht FROM cmdb_ci WHERE `name` = \'IPObject\' ))\n	)\n	UNION\n	select count(1) as count, \'IP软硬件\' as `name`, \'修改\' as type from cmdb_cientity_transaction where action = \'update\' and transaction_id in\n(\nSELECT\n	id\nFROM\n	cmdb_transaction \nWHERE\n  input_from = \'autoexec\'\n	and\n	ci_id IN (\n	SELECT\n		id \n	FROM\n		cmdb_ci \n	WHERE\n		lft &gt;= ( SELECT lft FROM cmdb_ci WHERE `name` = \'IPObject\' ) \n	AND rht &lt;= ( SELECT rht FROM cmdb_ci WHERE `name` = \'IPObject\' ))\n	)\n</select>\n	\n<select>	\nselect count(1) as count, \'软件服务\' as `name`, \'新增\' as typ