INSERT INTO `notify_policy` VALUES (775838723219456,'自动化通知策略','neatlogic.module.autoexec.notify.handler.AutoexecCombopNotifyPolicyHandler',0,'{\"conditionOptionList\":[],\"paramList\":[],\"templateList\":[{\"action\":\"update\",\"actionName\":\"编辑\",\"actionTime\":1757473263400,\"actionUser\":\"admin\",\"content\":\"<p style=\\\"font-size: 14px\\\">用户:${DATA.operator}发起的作业：[${DATA.jobId}]${DATA.jobName}执行失败！</p>\\n<p style=\\\"font-size: 14px\\\">失败阶段为：</p>\\n<#if DATA.jobPhaseList?? && (DATA.jobPhaseList?size > 0)>\\n  <table cellpadding=\\\"2\\\" cellspacing=\\\"0\\\" border=\\\"1\\\" style=\\\"border-collapse: collapse; font-size: 14px;width:100%;text-align:center;\\\">\\n  \\t<tr>\\n     <th>阶段名称</th>\\n     <th>执行方式</th>\\n\\t  <th>开始时间</th>\\n\\t  <th>结束时间</th>\\n   </tr>\\n   <#list DATA.jobPhaseList as item>\\n     <#if item.status == \'failed\'>\\n       <tr>\\n         <td>${item.name}</td>\\n         <td>${item.execMode}</td>\\n\\t\\t\\t<td>${(item.startTime)?string(\'yyyy-MM-dd HH:mm:ss\')}</td>\\n        <td>${(item.endTime)?string(\'yyyy-MM-dd HH:mm:ss\')}</td>\\n       </tr>  \\n     </#if>\\n   </#list>                         \\n\\t</table> \\n</#if>\\n<p style=\\\"font-size: 14px\\\">详细信息请访问<a href=\\\"${DATA.homeUrl}/autoexec.html#/job-detail?id=${DATA.id}\\\">作业详情</a>。</p>\",\"id\":775838991654912,\"name\":\"自动化失败通知\",\"notifyHandler\":\"MessageNotifyHandler\",\"policyLimit\":0,\"startPage\":1,\"title\":\"作业:[${DATA.jobId}]${DATA.jobName}执行提醒\"},{\"action\":\"create\",\"actionName\":\"创建\",\"actionTime\":1757473239040,\"actionUser\":\"admin\",\"content\":\"<p style=\\\"font-size: 14px\\\">用户:${DATA.operator}发起的作业：[${DATA.jobId}]${DATA.jobName}等待人工确认。</p>\\n<p style=\\\"font-size: 14px\\\">详细信息请访问<a href=\\\"${DATA.homeUrl}/autoexec.html#/job-detail?id=${DATA.id}\\\">作业详情</a>。</p>\",\"id\":1507141261205504,\"name\":\"人工确认模版\",\"notifyHandler\":\"MessageNotifyHandler\",\"policyLimit\":0,\"startPage\":1,\"title\":\"作业:[${DATA.jobId}]${DATA.jobName}执